<script setup>
defineProps({period:{type:String,default:'current'},dateFrom:String,dateTo:String,busy:Boolean})
defineEmits(['select','update:dateFrom','update:dateTo'])
const periods=[['current','يوم العمل الحالي'],['history','الطلبات السابقة'],['range','فترة محددة']]
</script>
<template><div class="admin-order-period"><div class="order-period-options" role="group" aria-label="فترة عرض الطلبات"><button v-for="[value,label] in periods" :key="value" type="button" class="row-button" :aria-pressed="period===value" :disabled="busy" @click="$emit('select',value)">{{ label }}</button></div><div v-if="period==='range'" class="order-period-dates"><label class="field">من يوم عمل<input :value="dateFrom" type="date" required :disabled="busy" @input="$emit('update:dateFrom',$event.target.value)"></label><label class="field">إلى يوم عمل<input :value="dateTo" type="date" required :min="dateFrom||undefined" :disabled="busy" @input="$emit('update:dateTo',$event.target.value)"></label></div><p class="catalog-note">{{ period==='current'?'تُعرض طلبات يوم العمل الحالي بتوقيت المطعم، مع احتساب الدوام الممتد بعد منتصف الليل.':period==='history'?'تُعرض الطلبات التي سبقت يوم العمل الحالي. يمكنك تحديد فترة لمراجعة أيام معينة.':'حدد أيام العمل ثم اضغط تطبيق الفلاتر.' }}</p></div></template>
<style scoped>
.admin-order-period{grid-column:1/-1;margin-bottom:16px;padding:14px;background:var(--cream);border:1px solid var(--line);border-radius:9px}.order-period-options{display:flex;gap:8px;flex-wrap:wrap}.order-period-options .row-button{margin:0;min-height:42px}.order-period-options [aria-pressed=true]{background:var(--burgundy);color:white}.order-period-dates{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}.order-period-dates .field{margin:0}.order-period-dates input{width:100%}.admin-order-period .catalog-note{margin:10px 0 0;font-size:12px;line-height:1.8}@media(max-width:600px){.order-period-dates{grid-template-columns:1fr}.order-period-options button{flex:1 1 130px}}
</style>
